const $=id=>document.getElementById(id),brief=$('brief'),purchase=$('purchase-list'),form=$('brief-form');
const catalog={towdesk:{name:'TowDesk'},novixdesk:{name:'NovixDesk'}};let list=[];try{list=JSON.parse(localStorage.getItem('gear-software-list')||'[]').filter(id=>catalog[id]);}catch{}let inquiry='',project='';
function download(text,name){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function renderList(){$('list-count').textContent=list.length;$('selected-products').replaceChildren();if(!list.length){const p=document.createElement('p');p.textContent='Your list is empty. Add an application from the store.';$('selected-products').append(p)}for(const id of list){const row=document.createElement('div');row.className='selected-product';const text=document.createElement('span');text.textContent=catalog[id].name+' — pricing on request';const remove=document.createElement('button');remove.type='button';remove.textContent='Remove';remove.onclick=()=>{list=list.filter(x=>x!==id);renderList()};row.append(text,remove);$('selected-products').append(row)}try{localStorage.setItem('gear-software-list',JSON.stringify(list))}catch{}document.querySelectorAll('[data-add]').forEach(b=>b.textContent=list.includes(b.dataset.add)?'In your list ✓':'Request a license ＋');$('purchase-form').querySelector('[type="submit"]').disabled=!list.length;inquiry='';$('download-inquiry').hidden=true;}
document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{if(!list.includes(b.dataset.add))list.push(b.dataset.add);renderList();purchase.showModal()});$('open-list').onclick=()=>{renderList();purchase.showModal()};
document.querySelectorAll('[data-brief],[data-custom]').forEach(b=>b.onclick=()=>{if(b.hasAttribute('data-custom'))form.elements.service.value='Custom software development';brief.showModal()});
document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}));
const menu=$('menu'),nav=document.querySelector('nav');menu.onclick=()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Close navigation':'Open navigation');nav.classList.toggle('open',open)};nav.querySelectorAll('a').forEach(a=>a.onclick=()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')});
let filter='all';function filterProducts(){const q=$('software-search').value.toLowerCase();let count=0;document.querySelectorAll('[data-category]').forEach(card=>{card.hidden=(filter!=='all'&&card.dataset.category!==filter)||!card.textContent.toLowerCase().includes(q);if(!card.hidden)count++});$('no-products').hidden=count>0;}
document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});filterProducts()});$('software-search').oninput=filterProducts;
form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;const d=new FormData(form);project=['Ubernyx Gear — Project enquiry','','Name: '+d.get('name'),'Email: '+d.get('email'),'Interested in: '+d.get('service'),'','Requirements:',d.get('details')].join('\n');$('fallback').hidden=false;location.href='mailto:info@ubernyx.com?subject='+encodeURIComponent('Software enquiry: '+d.get('service'))+'&body='+encodeURIComponent(project)};$('download').onclick=()=>download(project,'ubernyx-gear-project-brief.txt');
$('purchase-form').onsubmit=e=>{e.preventDefault();if(!list.length)return;const d=new FormData(e.currentTarget);inquiry=['Ubernyx Gear — Software purchase inquiry','','Applications: '+list.map(id=>catalog[id].name).join(', '),'Name: '+d.get('name'),'Email: '+d.get('email'),'Company: '+d.get('company'),'Users: '+d.get('users'),'Preferred delivery: '+d.get('delivery'),'','Requirements:',d.get('details')||'Please provide pricing, license terms, compatibility, and delivery options.','','This is an inquiry, not an order or payment.'].join('\n');$('download-inquiry').hidden=false;$('purchase-status').textContent='Inquiry prepared. Review and send it in your email app, or download it below. Nothing has been submitted through the website.';location.href='mailto:info@ubernyx.com?subject='+encodeURIComponent('Software purchase inquiry — '+list.map(id=>catalog[id].name).join(', '))+'&body='+encodeURIComponent(inquiry)};$('download-inquiry').onclick=()=>download(inquiry,'ubernyx-gear-purchase-inquiry.txt');$('year').textContent=new Date().getFullYear();renderList();
